package net.civeira.phylax.feature.observe.ingest;

import java.util.Collection;

import io.opentelemetry.sdk.common.CompletableResultCode;
import io.opentelemetry.sdk.logs.data.LogRecordData;
import io.opentelemetry.sdk.logs.export.LogRecordExporter;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.source.SourceRegistry;

/**
 * Receives the logs that the OTLP collector ({@code /v1/logs}) gets from the other origins. The own
 * logs are captured by {@link ObserveLogHandler}.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ObserveLogExporter implements LogRecordExporter {

  private final TelemetryMapper mapper;
  private final IngestContext context;
  private final ObservePipeline pipeline;
  private final SourceRegistry registry;
  private final net.civeira.phylax.feature.observe.metric.ObserveMetrics metrics;

  @Override
  public CompletableResultCode export(final Collection<LogRecordData> logs) {
    if (!context.inRequest()) {
      // Own logs exported by OpenTelemetry: already captured by the log handler
      return CompletableResultCode.ofSuccess();
    }
    var keySource = context.keySource();
    for (LogRecordData log : logs) {
      var source = mapper.resolve(true, keySource, log.getResource().getAttributes());
      if (source.isEmpty()) {
        registry.drop(null);
        continue;
      }
      registry.seen(source.get().code());
      if (!mapper.allow(source.get())) {
        continue;
      }
      mapper.log(source.get(), log).ifPresent(event -> {
        metrics.recordVital(event);
        pipeline.offer(event);
      });
    }
    return CompletableResultCode.ofSuccess();
  }

  @Override
  public CompletableResultCode flush() {
    return CompletableResultCode.ofSuccess();
  }

  @Override
  public CompletableResultCode shutdown() {
    return CompletableResultCode.ofSuccess();
  }
}
